/**
 * Applying the committed migrations.
 *
 * Every command runs this first, so `pnpm db:seed` on a fresh clone is one command rather than
 * two and `pnpm db:reset` cannot half-work against a schema from a previous checkout. The
 * migrations themselves are generated by `drizzle-kit generate` and committed under
 * `packages/db/drizzle/`; nothing here creates a table.
 */

import { migrate } from 'drizzle-orm/better-sqlite3/migrator';
import type { Db } from '../client';
import { MIGRATIONS_DIR } from '../paths';

export function migrateDatabase(db: Db): void {
  migrate(db, { migrationsFolder: MIGRATIONS_DIR });
}
